'use strict';
const $=(x)=>document.getElementById(x);
const esc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=(v)=>`AED ${Number(v||0).toLocaleString('en-AE',{minimumFractionDigits:2,maximumFractionDigits:2})}`;
const pretty=(v)=>({meta:'Meta Ads',google:'Google Ads',google_growth:'Google Growth',tiktok:'TikTok Ads',bookings:'Bookings',leads:'Enquiries',traffic:'Website traffic',awareness:'Awareness',owner:'Owner',manager:'Manager',viewer:'Viewer'}[v]||String(v??''));
const state={boot:null,workspace:null,tenant:null,view:'overview',lastAI:null,busy:false,analyticsRange:'last_30_days',googleAccounts:[],metaAssets:null,metaHealth:null,metaHealthLoading:false};
let toastTimeout;
const themeKey='adwise_product_theme';
function applyProductTheme(theme){const selected=theme==='light'?'light':'dark';document.documentElement.dataset.productTheme=selected;document.querySelectorAll('[data-theme-toggle]').forEach(button=>{button.textContent=selected==='dark'?'☀ Light':'☾ Dark';button.setAttribute('aria-pressed',String(selected==='light'))});document.querySelector('meta[name="theme-color"]')?.setAttribute('content',selected==='dark'?'#05060f':'#f5f6ff');try{localStorage.setItem(themeKey,selected)}catch{}}
try{applyProductTheme(localStorage.getItem(themeKey)||'dark')}catch{applyProductTheme('dark')}
function toast(text,bad=false){const el=$('toast');el.textContent=text;el.className=`toast${bad?' bad':''}`;clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>el.classList.add('hidden'),4800)}
async function req(url,method='GET',body){let opt={method,credentials:'same-origin',headers:{}};if(body!==undefined){opt.headers['Content-Type']='application/json';opt.body=JSON.stringify(body)}if(method!=='GET'&&state.boot?.csrf){opt.headers['X-CSRF-Token']=state.boot.csrf}let r;try{r=await fetch(url,opt)}catch{throw Error('Network unavailable. Check your connection.')}const x=await r.json().catch(()=>({}));if(!r.ok)throw Error(typeof x.detail==='string'?x.detail:`Request failed (${r.status})`);return x}
function showAuth(){state.boot=null;$('app').classList.add('hidden');$('login').classList.remove('hidden')}
function setMobileMenu(open){document.body.classList.toggle('mobile-menu-open',open);$('mobileMenuButton')?.setAttribute('aria-expanded',String(open));}
function showApp(){ $('login').classList.add('hidden');$('app').classList.remove('hidden');$('userEmail').textContent=state.boot.user.email;$('userRoleLabel').textContent=state.boot.super_admin?'Super Admin':'Workspace Owner';$('superAdminLink').classList.toggle('hidden',!state.boot.super_admin);const sel=$('tenantSelect');sel.innerHTML=state.boot.tenants.map(t=>`<option value="${esc(t.id)}">${esc(t.name)}</option>`).join('');if(!state.tenant || !state.boot.tenants.some(t=>t.id===state.tenant))state.tenant=state.boot.tenants[0]?.id;sel.value=state.tenant;}
async function refresh(){state.boot=await req('/api/bootstrap');showApp();if(state.tenant)await loadTenant(state.tenant)}
async function loadTenant(id){state.tenant=id;state.workspace=await req(`/api/workspaces/${encodeURIComponent(id)}`);if(state.workspace.google_metrics?.range)state.analyticsRange=state.workspace.google_metrics.range;$('tenantSelect').value=id;render()}
async function autoSyncConnectedData(){const workspace=state.workspace,tenant=state.tenant;if(!workspace||!tenant)return;const jobs=[];if(workspace.integrations?.google?.status==='connected')jobs.push(req(`/api/workspaces/${encodeURIComponent(tenant)}/integrations/google/sync?range=${encodeURIComponent(state.analyticsRange)}`,'POST',{}).then(data=>['google_metrics',data]));if(workspace.integrations?.google_growth?.status==='connected')jobs.push(req(`/api/workspaces/${encodeURIComponent(tenant)}/integrations/google-growth/sync`,'POST',{}).then(data=>['growth_metrics',data]));if(workspace.integrations?.meta?.status==='connected'&&workspace.current_role==='owner')jobs.push(req(`/api/workspaces/${encodeURIComponent(tenant)}/integrations/meta/sync?range=${encodeURIComponent(state.analyticsRange)}`,'POST',{}).then(data=>['meta_metrics',data]));if(!jobs.length)return;document.body.classList.add('data-syncing');const results=await Promise.allSettled(jobs);if(state.tenant===tenant){for(const result of results)if(result.status==='fulfilled'){const [key,value]=result.value;if(key==='meta_metrics')state.workspace.meta={...(state.workspace.meta||{}),metrics:value};else state.workspace[key]=value}render()}document.body.classList.remove('data-syncing')}
function section(name,title,subtitle,action=''){ $('currentBread').textContent=name.toUpperCase();$('pageEyebrow').textContent=name==='Overview'?'CAMPAIGN INTELLIGENCE':'GROWTH WORKSPACE';$('pageTitle').innerHTML=title;$('pageSubtitle').textContent=subtitle;$('headAction').innerHTML=action;document.querySelectorAll('.nav-item[data-view]').forEach(x=>x.classList.toggle('selected',x.dataset.view===state.view));$('approvalBadge').textContent=state.workspace?.counts?.pending?state.workspace.counts.pending:'';$('approvalBadge').style.display=state.workspace?.counts?.pending?'inline-block':'none'}
function btn(label,action,style='secondary',attrs=''){return `<button type="button" class="${style}" data-action="${action}" ${attrs}>${label}</button>`}
function badge(s){return `<span class="badge ${esc(s)}">${esc(s==='approved'?'Approved internally':s)}</span>`}
function campaignTable(cs){if(!cs.length)return `<div class="empty"><span class="empty-icon">◈</span><h3>Your first campaign starts here</h3><p>Create a draft or use the AI Studio to shape an offer, then move it through the approval workflow.</p>${btn('＋ Create campaign','new-campaign','primary')}</div>`;return `<div class="table-wrap"><table class="table"><thead><tr><th>Campaign</th><th>Platform / Objective</th><th>Planned budget</th><th>Status</th><th>Action</th></tr></thead><tbody>${cs.map(c=>`<tr><td><strong>${esc(c.name)}</strong><small>${esc(c.service||'General campaign')} · ${esc((c.created_at||'').slice(0,10))}</small></td><td>${esc(pretty(c.provider))}<small>${esc(pretty(c.objective))}</small></td><td><b>${esc(money(c.budget_aed))}</b><small>Approved ceiling</small></td><td>${c.publication?.status==='created'?'<span class="badge approved">Created · paused</span>':c.publication?.status==='active'?'<span class="badge approved">Live · active</span>':c.publication?.status==='paused'?'<span class="badge pending">Live · paused</span>':c.publication?.status==='failed'&&c.provider==='meta'?'<span class="badge rejected">Launch failed</span>':(state.workspace?.meta?.change_requests||[]).some(r=>r.campaign_id===c.id&&r.status==='awaiting_owner')?'<span class="badge pending">Launch awaiting owner</span>':badge(c.status)}</td><td><div class="line-actions">${c.status==='draft'?btn('Submit','submit','secondary mini',`data-id="${esc(c.id)}"`):''}${c.status==='pending'?btn('Approve','approve','primary mini',`data-id="${esc(c.id)}"`)+btn('Reject','reject','danger mini',`data-id="${esc(c.id)}"`):''}${c.status==='approved'&&c.provider==='google'&&c.publication?.status!=='created'?btn('Create in Google Ads','publish-google','primary mini',`data-id="${esc(c.id)}"`):''}${['pending','approved'].includes(c.status)&&c.provider==='meta'&&!['created','active','paused'].includes(c.publication?.status)&&!(state.workspace?.meta?.change_requests||[]).some(r=>r.campaign_id===c.id&&r.status==='awaiting_owner')&&['owner','manager'].includes(state.workspace?.current_role)?btn('Request Meta launch','publish-meta','primary mini',`data-id="${esc(c.id)}"`):''}${c.status!=='archived'?btn('Archive','archive','ghost mini',`data-id="${esc(c.id)}"`):''}</div></td></tr>`).join('')}</tbody></table></div>`}
function overview(){const d=state.workspace;section('Overview',`Advertising, <span class="accent">simplified.</span>`,`Welcome to ${d.tenant.name}. Plan, review and organize ads without risking live spend.`,btn('＋ New campaign','new-campaign','primary'));const k=[['Campaign drafts',d.counts.draft,'◈','Ready to be refined'],['Awaiting approval',d.counts.pending,'◷','Owner review required'],['Internally approved',d.counts.approved,'✓','Not yet published'],['Planned approvals',money(d.settings.approved_budget_aed),'◉','AED of internally approved budgets']];$('viewContent').innerHTML=`<div class="grid kpis">${k.map(c=>`<div class="card"><span class="icon">${c[2]}</span><span class="title">${esc(c[0])}</span><div class="value">${esc(c[1])}</div><span class="tiny">${esc(c[3])}</span></div>`).join('')}</div><div class="grid two-col"><div><div class="hero"><div><span class="eyebrow">MEET YOUR AI CAMPAIGN PARTNER</span><h2>Plan your next best campaign.</h2><p>Turn a treatment, objective and budget into a reviewable strategy. Launching stays separate from planning.</p></div>${btn('✦ Start planning','go-assistant','primary')}</div><div class="panel" style="margin-top:20px"><div class="panel-heading"><h3>Recent campaign activity</h3>${btn('View all →','go-campaigns','ghost mini')}</div>${campaignTable(d.campaigns.slice(0,5))}</div></div><div><div class="panel panel-pad"><h3>Launch readiness</h3><p class="sub">This is a standalone planning MVP. To run real ads, external API authorization and a reviewed publisher are required.</p><div class="checklist"><div class="check"><span class="check-icon">✓</span><div><b>Workspace secured</b><small>Owner-only access, private sessions and tenant separation.</small></div></div><div class="check"><span class="check-icon">✓</span><div><b>Approval and budget rules</b><small>Campaigns need owner approval; spending cap checked on the server.</small></div></div><div class="check"><span class="check-icon">${state.boot.ai_configured?'✓':'○'}</span><div><b>AI generation ${state.boot.ai_configured?'configured':'not connected'}</b><small>${state.boot.ai_configured?'MiniMax-powered planning and research enabled.':'Set the server AI credentials for true AI responses.'}</small></div></div><div class="check"><span class="check-icon">○</span><div><b>Advertising accounts</b><small>Official Google/Meta paid advertising OAuth not yet connected.</small></div></div></div><div class="notice warning">No live campaign metrics or actual spend available. All budgets shown are internal plans, not advertising charges.</div></div><div class="panel panel-pad" style="margin-top:20px"><h3>Safety status</h3><p class="sub">Automation mode: <b>${esc(d.settings.mode)}</b> · Owner cap: <b>${esc(money(d.settings.budget_limit_aed))}</b></p>${d.settings.stopped?'<div class="notice warning">Emergency stop active. Internal AI planning and approvals are blocked.</div>':'<div class="notice info">Safe planning enabled. External ad publishing is disabled.</div>'}</div></div></div>`}
function campaigns(){const d=state.workspace;section('Campaigns',`Campaign <span class="accent">library.</span>`,`Plan, approve and create complete Google Search or Meta campaigns.`,btn('＋ Create campaign','new-campaign','primary'));$('viewContent').innerHTML=`<div class="notice" style="margin-bottom:18px">After approval, Adwise can create Google Search or Meta campaign resources <b>paused</b>. Enabling spend is always a separate action.</div><div class="panel"><div class="panel-heading"><h3>All campaigns <span class="muted">(${d.campaigns.length})</span></h3><span class="pill">${d.counts.pending} awaiting approval</span></div>${campaignTable(d.campaigns)}</div>`}
function approvals(){const d=state.workspace;const pending=d.campaigns.filter(c=>c.status==='pending');section('Approvals',`Campaign <span class="accent">approvals.</span>`,`Review the scope, creative and planned budget before signing off.`);$('viewContent').innerHTML=`<div class="notice" style="margin-bottom:20px">Campaign approval below authorizes the plan and budget inside Adswise. Meta launches and live changes are approved separately in <b>Live Meta changes</b>, and only after Seed validation passes 100%.</div>${metaRequestsPanel()}<div class="panel"><div class="panel-heading"><h3>Pending decisions</h3><span class="badge pending">${pending.length} pending</span></div>${campaignTable(pending)}</div><div class="panel panel-pad" style="margin-top:20px"><h3>Approval rules</h3><div class="checklist"><div class="check"><span class="check-icon">✓</span><div><b>Owner confirmation</b><small>Approvals require the active owner session and CSRF validation.</small></div></div><div class="check"><span class="check-icon">✓</span><div><b>Workspace cap</b><small>Sum of internally approved budgets cannot exceed the configured allowance.</small></div></div><div class="check"><span class="check-icon">✓</span><div><b>Global stop</b><small>Emergency stop prevents new approvals and agent planning.</small></div></div></div></div>`}
function assistant(){section('AI Campaign Studio',`A creative partner for <span class="accent">growth.</span>`,`Brief the agent, get a structured campaign proposal, and save it as a draft.`);$('viewContent').innerHTML=`<div class="grid ai-grid"><div class="panel panel-pad"><div class="agent-intro"><span>✦</span><h3>Campaign Strategy Assistant</h3><p>Turn your services and objectives into a thoughtful advertising plan. AI-generated outputs are drafts and always require review.</p><span class="pill">${state.boot.ai_configured?'AI model connected':'Template planning mode'}</span></div><form id="agentForm" class="form-fields"><label>Which service do you want to promote?<input name="service" required maxlength="120" placeholder="e.g., Deep tissue massage"></label><label>Advertising channel<select name="provider"><option value="meta">Meta Ads (Facebook & Instagram)</option><option value="google">Google Ads</option></select></label><label>Your primary objective<select name="objective"><option value="bookings">Increase bookings</option><option value="leads">Generate qualified enquiries</option><option value="traffic">Bring visitors to the booking website</option><option value="awareness">Increase local brand awareness</option></select></label><label>Proposed total budget (AED)<input name="budget_aed" type="number" min="1" step="0.01" value="500" required></label><label>Tell the agent your goal<textarea rows="5" name="brief" required maxlength="3000" placeholder="Example: Promote our 60-minute massage package to people near our Dubai branch. Do not offer discounts without my approval."></textarea></label><button class="primary" type="submit">✦ ${state.boot.ai_configured?'Generate AI campaign plan':'Generate planning template'} →</button></form></div><div class="panel panel-pad"><h3>Campaign plan</h3><p class="sub">Your strategy appears here. It never launches automatically.</p><div id="aiOutput" class="agent-output">${state.lastAI?esc(state.lastAI.plan):'No plan generated yet. Complete the brief on the left to get started.'}</div><div style="margin-top:18px;display:flex;gap:9px;flex-wrap:wrap">${state.lastAI?btn('Save plan as campaign draft','save-plan','primary'):''}<span class="badge">No ad spend</span></div><hr><span class="eyebrow">SAFETY BY DESIGN</span><p class="sub">Never assume generated promises, discounts, targeting, projected revenue or pricing are correct. Validate against your service catalogue and provider advertising rules.</p></div></div>`}
function googleMetricsPanel(m){if(!m)return `<div class="panel panel-pad" style="margin-top:20px"><h3>Live Google Ads performance</h3><p class="sub">No metrics synced yet. Use “Sync last 30 days” above.</p></div>`;const t=m.totals||{},rows=m.campaigns||[],goals=m.conversion_actions||[];return `<div class="panel panel-pad" style="margin-top:20px"><div class="panel-heading" style="padding:0 0 16px"><div><h3>Live Google Ads performance</h3><p class="sub">${esc(m.period||'Google Ads')} · Synced ${esc((m.synced_at||'').replace('T',' ').slice(0,16))} UTC</p></div><span class="badge approved">Supervised controls</span></div><div class="stat-strip"><span>Impressions: ${Number(t.impressions||0).toLocaleString()}</span><span>Clicks: ${Number(t.clicks||0).toLocaleString()}</span><span>CTR: ${esc(t.ctr_percent||0)}%</span><span>Cost: ${esc(money(t.cost_aed||0))}</span><span>Conversions: ${esc(t.conversions||0)}</span></div>${rows.length?`<div class="table-wrap" style="margin-top:18px"><table class="table"><thead><tr><th>Campaign</th><th>Status / Type</th><th>Impressions</th><th>Clicks</th><th>Cost</th><th>Conversions</th><th>Control</th></tr></thead><tbody>${rows.map(c=>`<tr><td><strong>${esc(c.name)}</strong><small>ID ${esc(c.id)}</small></td><td>${esc(c.status)}<small>${esc(c.channel)}</small></td><td>${Number(c.impressions||0).toLocaleString()}</td><td>${Number(c.clicks||0).toLocaleString()}</td><td>${esc(money(c.cost_aed||0))}</td><td>${esc(c.conversions||0)}</td><td>${c.status==='ENABLED'?btn('Pause','google-campaign-pause','danger mini',`data-id="${esc(c.id)}"`):c.status==='PAUSED'?btn('Enable','google-campaign-enable','primary mini',`data-id="${esc(c.id)}"`):''}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><h3>No campaign activity</h3><p>Google returned no campaign metrics for the last 30 days.</p></div>'}<hr><div class="panel-heading" style="padding:0"><div><h3>Conversion goals</h3><p class="sub">Completed bookings, WhatsApp clicks and phone calls.</p></div>${btn(goals.length?'Recheck goals':'Set up all three','google-conversions-setup','secondary')}</div>${goals.length?`<div class="checklist">${goals.map(g=>`<div class="check"><span class="check-icon">✓</span><div><b>${esc(g.name)}</b><small>${esc(g.status)} · ${esc(g.type)} · Website tag installation required</small></div></div>`).join('')}</div>`:'<div class="notice warning">The three Google Ads conversion actions have not been configured yet.</div>'}</div>`}
function trendChart(rows,key,color='#4169ff'){if(!rows.length)return '<div class="chart-empty">Sync Google Ads to load the daily trend.</div>';const vals=rows.map(x=>Number(x[key]||0)),max=Math.max(...vals,1),w=720,h=250,p=28,step=(w-p*2)/Math.max(rows.length-1,1),pts=vals.map((v,i)=>`${p+i*step},${h-p-(v/max)*(h-p*2)}`),area=`M ${p},${h-p} L ${pts.join(' L ')} L ${p+(rows.length-1)*step},${h-p} Z`;return `<svg class="trend-chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(key)} trend"><defs><linearGradient id="fill-${esc(key)}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${color}" stop-opacity=".25"/><stop offset="1" stop-color="${color}" stop-opacity=".02"/></linearGradient></defs>${[0,.25,.5,.75,1].map(v=>`<line x1="${p}" y1="${p+v*(h-p*2)}" x2="${w-p}" y2="${p+v*(h-p*2)}" stroke="#e1e5f4"/>`).join('')}<path d="${area}" fill="url(#fill-${esc(key)})"/><polyline points="${pts.join(' ')}" fill="none" stroke="${color}" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/>${pts.map((pt,i)=>`<circle cx="${pt.split(',')[0]}" cy="${pt.split(',')[1]}" r="3" fill="${color}"><title>${esc(rows[i].date)}: ${esc(vals[i])}</title></circle>`).join('')}<text x="${p}" y="${h-5}" class="chart-label">${esc(rows[0].date.slice(5))}</text><text x="${w-p}" y="${h-5}" text-anchor="end" class="chart-label">${esc(rows.at(-1).date.slice(5))}</text></svg>`}
function campaignBars(rows){if(!rows.length)return '<div class="chart-empty">No campaign data available.</div>';const max=Math.max(...rows.map(x=>Number(x.clicks||0)),1);return `<div class="campaign-bars">${rows.map(c=>`<div class="bar-row"><div><b>${esc(c.name)}</b><small>${Number(c.impressions||0).toLocaleString()} impressions · ${esc(money(c.cost_aed||0))}</small></div><div class="bar-track"><i style="width:${Math.max(2,Number(c.clicks||0)*100/max)}%"></i></div><strong>${Number(c.clicks||0).toLocaleString()} clicks</strong></div>`).join('')}</div>`}
function analytics(){const d=state.workspace,m=d.google_metrics,g=d.integrations?.google||{};section('Analytics',`Campaign <span class="accent">analytics.</span>`,`Live Google Ads performance for the last 30 days.`,g.status==='connected'?btn('↻ Refresh analytics','google-sync','primary'):'');if(!m){$('viewContent').innerHTML=`<div class="panel empty"><span class="empty-icon">⌁</span><h3>No analytics snapshot yet</h3><p>Connect Google Ads and sync the last 30 days to populate this dashboard.</p>${g.status==='connected'?btn('Sync now','google-sync','primary'):'<button class="secondary" data-view="accounts">Open Ad Accounts</button>'}</div>`;return}const t=m.totals||{},daily=m.daily||[],cpc=Number(t.clicks)?Number(t.cost_aed)/Number(t.clicks):0,cvr=Number(t.clicks)?Number(t.conversions)*100/Number(t.clicks):0;$('viewContent').innerHTML=`<div class="grid analytics-kpis"><div class="card"><span class="icon">◉</span><span class="title">Impressions</span><div class="value">${Number(t.impressions||0).toLocaleString()}</div><span class="tiny">Ad views</span></div><div class="card"><span class="icon">↗</span><span class="title">Clicks</span><div class="value">${Number(t.clicks||0).toLocaleString()}</div><span class="tiny">${esc(t.ctr_percent||0)}% click-through rate</span></div><div class="card"><span class="icon">د.إ</span><span class="title">Spend</span><div class="value">${esc(money(t.cost_aed||0))}</div><span class="tiny">${esc(money(cpc))} average CPC</span></div><div class="card"><span class="icon">✓</span><span class="title">Conversions</span><div class="value">${esc(t.conversions||0)}</div><span class="tiny">${cvr.toFixed(2)}% conversion rate</span></div></div><div class="grid analytics-grid"><div class="panel panel-pad"><div class="chart-head"><div><h3>Daily spend</h3><p class="sub">AED across all connected campaigns</p></div><span class="badge">30 days</span></div>${trendChart(daily,'cost_aed','#4169ff')}</div><div class="panel panel-pad"><div class="chart-head"><div><h3>Daily clicks</h3><p class="sub">Traffic generated from Google Ads</p></div><span class="badge">30 days</span></div>${trendChart(daily,'clicks','#32d7d5')}</div></div><div class="panel panel-pad" style="margin-top:18px"><div class="chart-head"><div><h3>Campaign comparison</h3><p class="sub">Clicks, impressions and spend by campaign</p></div><span class="badge approved">Live data</span></div>${campaignBars(m.campaigns||[])}</div><p class="analytics-note">Synced ${esc((m.synced_at||'').replace('T',' ').slice(0,16))} UTC · Conversion totals remain zero until website tracking tags are installed.</p>`}
function accounts(){const d=state.workspace,g=d.integrations?.google||{status:'not_connected'},connected=g.status==='connected',authorized=g.status==='authorized';section('Ad Accounts',`Platform <span class="accent">connections.</span>`,`Connect and supervise official paid advertising accounts.`,connected?btn('↻ Sync last 30 days','google-sync','primary'):'');const accountText=connected?`${esc(g.account_name||'Google Ads account')} · Customer ${esc(g.customer_id)}${g.login_customer_id?` · Manager ${esc(g.login_customer_id)}`:''}`:authorized?'OAuth complete. Choose the Google Ads account for this workspace.':'Connect the Google user who can access this business’s Ads account.';$('viewContent').innerHTML=`<div class="notice ${connected?'info':'warning'}" style="margin-bottom:20px">${connected?`Google Ads account <b>${esc(g.customer_id)}</b> is securely connected to this workspace.`:authorized?'Google OAuth is authorized. Select the correct account before syncing or publishing.':'Connect Google Ads through the official authorization screen.'}</div><div class="grid settings-grid"><div class="panel panel-pad"><h3>Advertising platforms</h3><div class="provider"><span class="provider-logo">G</span><div class="details"><h4>Google Ads</h4><p>${accountText}</p></div><span class="badge ${connected?'approved':authorized?'pending':''}">${esc(connected?'Connected':authorized?'Account required':'Not connected')}</span></div><div style="display:flex;gap:9px;margin:12px 0 20px;flex-wrap:wrap">${authorized?btn('Choose Google Ads account','google-select-account','primary'):btn(connected?'Reconnect Google Ads':'Connect Google Ads','google-connect','primary')}${connected?btn('Set up 3 conversion goals','google-conversions-setup','secondary'):''}${connected||authorized?btn('Disconnect','google-disconnect','danger'):''}</div><div class="provider"><span class="provider-logo">M</span><div class="details"><h4>Meta Ads</h4><p>Facebook and Instagram integration is not connected.</p></div><span class="badge">Not connected</span></div></div><div class="panel panel-pad"><h3>Connection safeguards</h3><div class="checklist"><div class="check"><span class="check-icon">✓</span><div><b>Official Google OAuth</b><small>Authorization uses Google Accounts and the Google Ads scope.</small></div></div><div class="check"><span class="check-icon">✓</span><div><b>Encrypted refresh token</b><small>The long-lived credential is encrypted before database storage.</small></div></div><div class="check"><span class="check-icon">✓</span><div><b>Tenant-specific account</b><small>Each workspace must select an account accessible to its own Google login.</small></div></div><div class="check"><span class="check-icon">○</span><div><b>Website tags still required</b><small>Google conversion actions alone cannot record bookings, WhatsApp clicks or calls until their snippets are installed on the public website.</small></div></div></div></div></div>${connected?googleMetricsPanel(d.google_metrics):''}`}
function settings(){const d=state.workspace,owner=d.current_role==='owner',members=d.members||[];section('Controls & Team',`Control the <span class="accent">boundaries.</span>`,`Tenant roles protect campaigns, budgets and advertising connections.`);$('viewContent').innerHTML=`<div class="grid settings-grid"><div class="panel panel-pad"><h3>Automation and spending policy</h3><p class="sub">The cap controls the sum of internally approved draft budgets. It is not a provider-side spending guarantee.</p>${owner?`<form id="settingsForm" class="form-fields"><label>Planning mode<select name="mode"><option value="manual" ${d.settings.mode==='manual'?'selected':''}>Manual</option><option value="supervised" ${d.settings.mode==='supervised'?'selected':''}>Supervised (recommended)</option><option value="autonomous" ${d.settings.mode==='autonomous'?'selected':''}>Autonomous (policy only)</option></select></label><label>Maximum approved budget (AED)<input name="budget_limit_aed" type="number" step="0.01" min="0" value="${esc(d.settings.budget_limit_aed)}" required></label><button class="primary" type="submit">Save controls →</button></form>`:'<div class="notice info">Only the workspace owner can change budgets and automation controls.</div>'}</div><div class="panel panel-pad"><h3>Team access</h3><p class="sub">Owners control accounts and approvals. Managers create campaign drafts. Viewers have read-only access.</p><div class="checklist">${members.map(m=>`<div class="check"><span class="check-icon">${m.role==='owner'?'◆':'○'}</span><div><b>${esc(m.email)}</b><small>${esc(pretty(m.role))}</small></div></div>`).join('')}</div>${owner?`<hr><form id="inviteForm" class="form-fields"><label>Email address<input name="email" type="email" required></label><label>Role<select name="role"><option value="manager">Manager</option><option value="viewer">Viewer</option></select></label><button class="secondary" type="submit">Create invitation link</button></form>`:''}</div><div class="panel panel-pad"><h3>Emergency stop</h3><div class="notice ${d.settings.stopped?'warning':'info'}" style="margin-bottom:18px">${d.settings.stopped?'● Stop is ACTIVE.':'● No emergency stop active.'}</div>${owner?(d.settings.stopped?btn('Resume supervised planning','resume','primary'):btn('STOP internal automation','stop','danger')):''}</div><div class="panel panel-pad"><h3>Privacy and isolation</h3><p class="sub">HttpOnly sessions, origin checks, CSRF protection, password hashing, encrypted provider tokens, tenant-scoped access and an audit trail.</p><p class="sub">Your role: <b>${esc(pretty(d.current_role))}</b></p></div></div>`}
function activity(){const d=state.workspace;section('Activity Log',`Every action, <span class="accent">accountable.</span>`,`Review campaign and policy changes for this spa workspace.`);$('viewContent').innerHTML=`<div class="panel"><div class="panel-heading"><h3>Recent activity</h3><span class="badge">Last 40 entries</span></div>${!d.audit.length?'<div class="empty"><span class="empty-icon">◷</span><h3>No activity yet</h3><p>Actions taken in this workspace will appear here.</p></div>':d.audit.map(x=>`<div class="audit-row"><div><b>${esc(x.action.replaceAll('.',' / ').replaceAll('_',' '))}</b><p>${esc(x.email||'System')} · ${esc(JSON.stringify(x.detail).slice(0,400))}</p></div><time>${esc((x.created_at||'').replace('T',' ').slice(0,16))} UTC</time></div>`).join('')}</div>`}
function seedAnalysisPanel(){const latest=state.workspace.seed_analysis,a=latest?.analysis,f=a?.forecast||{};return `<div class="panel panel-pad seed-analysis"><div class="panel-heading"><div><span class="eyebrow">SEED PERFORMANCE ANALYST</span><h3>Predict and improve campaign performance</h3><p class="sub">Tenant-scoped aggregate data only. Recommendations never change a live campaign automatically.</p></div>${state.boot.seed_configured?btn(latest?'Analyze latest data again':'Analyze with Seed','seed-analyze','primary'):'<span class="badge">Server setup required</span>'}</div>${a?`<div class="notice info"><b>${esc(a.executive_summary)}</b><p>Confidence: ${esc(a.confidence)} · Model: ${esc(latest.model||'Seed')} · ${esc((latest.created_at||'').replace('T',' ').slice(0,16))} UTC</p></div><div class="grid kpis seed-forecast"><div class="card"><span class="title">Predicted clicks</span><div class="value">${f.next_30_day_clicks==null?'—':Number(f.next_30_day_clicks).toLocaleString()}</div><span class="tiny">Next 30 days</span></div><div class="card"><span class="title">Predicted conversions</span><div class="value">${f.next_30_day_conversions==null?'—':Number(f.next_30_day_conversions).toLocaleString()}</div></div><div class="card"><span class="title">Predicted CPA</span><div class="value">${f.predicted_cpa_aed==null?'—':money(f.predicted_cpa_aed)}</div></div></div><p class="sub">${esc(f.basis||'')}</p><div class="seed-recommendations">${(a.recommendations||[]).map(r=>`<article><span class="badge ${esc(r.priority)}">${esc(r.priority)} priority</span><h4>${esc(r.title)}</h4><p>${esc(r.action)}</p><small>${esc(r.rationale)} · Watch: ${esc(r.metric_to_watch)}</small><div class="notice warning">Owner approval required before applying this change.</div></article>`).join('')}</div>${a.data_quality_notes?.length?`<div class="notice warning"><b>Data quality</b>${a.data_quality_notes.map(x=>`<p>${esc(x)}</p>`).join('')}</div>`:''}`:'<div class="empty"><p>Run an analysis after syncing Google Ads and collecting website behavior data.</p></div>'}</div>`}
function analyticsV2(){analytics();const labels={yesterday:'Yesterday',this_week:'This week',last_week:'Last week',last_30_days:'Last 30 days'},bar=document.createElement('div');bar.className='panel panel-pad';bar.style.marginBottom='18px';bar.innerHTML=`<div class="line-actions">${Object.entries(labels).map(([key,label])=>btn(label,'analytics-range',key===state.analyticsRange?'primary mini':'secondary mini',`data-range="${key}"`)).join('')}</div><p class="sub" style="margin:10px 0 0">Reporting period: <b>${esc(state.workspace.google_metrics?.period||labels[state.analyticsRange])}</b></p>`;$('viewContent').prepend(bar);if(state.workspace.integrations?.meta?.status==='connected')$('viewContent').insertAdjacentHTML('beforeend',metaMetricsPanel());$('viewContent').insertAdjacentHTML('beforeend',seedAnalysisPanel())}
function growthActions(){const connected=state.workspace.integrations?.google_growth?.status==='connected';return connected?`${btn('↻ Sync data','growth-sync','primary')}${btn('Disconnect','growth-disconnect','danger')}`:btn('Connect Google','growth-connect','primary')}
function ga4Panel(m){const g=m?.google_analytics,t=g?.totals||{};return `<div class="panel panel-pad" style="margin-top:18px"><div class="panel-heading" style="padding:0 0 16px"><div><h3>Google Analytics 4</h3><p class="sub">Website traffic for the previous 30 complete days. Only this workspace’s assigned property is displayed.</p></div>${g?'<span class="badge approved">Live GA4 data</span>':'<span class="badge">Not assigned</span>'}</div><form id="ga4PropertyForm" class="form-fields"><label>Exact GA4 property ID<input name="property" value="${esc(g?.property||'')}" placeholder="properties/123456789" pattern="properties/[0-9]+" required></label><button class="secondary" type="submit">Verify & assign to this workspace</button></form>${g?`<div class="grid kpis" style="margin-top:18px"><div class="card"><span class="title">Active users</span><div class="value">${Number(t.activeUsers||0).toLocaleString()}</div></div><div class="card"><span class="title">New users</span><div class="value">${Number(t.newUsers||0).toLocaleString()}</div></div><div class="card"><span class="title">Sessions</span><div class="value">${Number(t.sessions||0).toLocaleString()}</div></div><div class="card"><span class="title">Events</span><div class="value">${Number(t.eventCount||0).toLocaleString()}</div></div></div><div class="table-wrap" style="margin-top:18px"><table class="table"><thead><tr><th>Top page</th><th>Sessions</th><th>Active users</th></tr></thead><tbody>${(g.top_pages||[]).map(x=>`<tr><td><strong>${esc(x.page||'/')}</strong></td><td>${Number(x.sessions||0).toLocaleString()}</td><td>${Number(x.active_users||0).toLocaleString()}</td></tr>`).join('')||'<tr><td colspan="3">No page activity returned.</td></tr>'}</tbody></table></div>`:'<div class="notice info" style="margin-top:18px">Enter this workspace’s exact GA4 property ID to load its data. Other profiles are never listed.</div>'}</div>`}
function seo(){const d=state.workspace,m=d.growth_metrics,s=m?.search_console,t=s?.totals||{},sites=m?.search_console_sites||[],connected=d.integrations?.google_growth?.status==='connected';section('SEO Console',`Turn search into <span class="accent">customers.</span>`,`Monitor Search Console, Google Analytics and landing-page performance for this workspace.`,growthActions());if(!connected){$('viewContent').innerHTML='<div class="panel empty"><span class="empty-icon">↗</span><h3>Connect Google growth services</h3><p>Each tenant authorizes its own Google account. Adwise stores the authorization encrypted and keeps data inside that workspace.</p></div>';return}const sitePicker=sites.length?`<div class="panel panel-pad" style="margin-bottom:18px"><form id="searchConsolePropertyForm" class="form-fields"><label>Search Console property<select name="site_url" required>${sites.map(x=>`<option value="${esc(x.siteUrl)}" ${x.siteUrl===s?.site_url?'selected':''}>${esc(x.siteUrl)}</option>`).join('')}</select></label><button class="secondary" type="submit">Use this property</button></form></div>`:'';if(!s){$('viewContent').innerHTML=`${sitePicker}<div class="panel empty"><span class="empty-icon">↗</span><h3>No Search Console performance yet</h3><p>Sync the connected properties to load the previous 30 complete days.</p>${btn('Sync now','growth-sync','primary')}</div>${ga4Panel(m)}${m?.errors?.length?`<div class="notice warning" style="margin-top:18px">${m.errors.map(esc).join(' · ')}</div>`:''}`;return}const table=(rows,label)=>`<div class="panel panel-pad"><h3>${label}</h3><div class="table-wrap"><table class="table"><thead><tr><th>${label==='Top queries'?'Query':'Page'}</th><th>Clicks</th><th>Impressions</th></tr></thead><tbody>${(rows||[]).map(x=>`<tr><td><strong>${esc(x.name)}</strong></td><td>${Number(x.clicks||0).toLocaleString()}</td><td>${Number(x.impressions||0).toLocaleString()}</td></tr>`).join('')||'<tr><td colspan="3">No rows returned.</td></tr>'}</tbody></table></div></div>`;const sitemapDefault=s.site_url.startsWith('https://')?new URL('/sitemap.xml',s.site_url).href:'';$('viewContent').innerHTML=`${sitePicker}<div class="grid kpis"><div class="card"><span class="title">Organic clicks</span><div class="value">${Number(t.clicks||0).toLocaleString()}</div><span class="tiny">Last 30 complete days</span></div><div class="card"><span class="title">Impressions</span><div class="value">${Number(t.impressions||0).toLocaleString()}</div><span class="tiny">Google Search visibility</span></div><div class="card"><span class="title">Average CTR</span><div class="value">${esc(t.ctr_percent||0)}%</div><span class="tiny">Clicks per impression</span></div><div class="card"><span class="title">Average position</span><div class="value">${esc(t.position||0)}</div><span class="tiny">Across returned queries</span></div></div><div class="notice info" style="margin:18px 0">Property: <b>${esc(s.site_url)}</b> · ${esc(s.start_date)} to ${esc(s.end_date)}</div><div class="grid settings-grid">${table(s.top_queries,'Top queries')}${table(s.top_pages,'Top pages')}</div><div class="panel panel-pad" style="margin-top:18px"><h3>Submit a sitemap</h3><p class="sub">Send an approved tenant sitemap directly to the connected Search Console property.</p><form id="sitemapForm" class="form-fields"><label>Search Console property<input name="site_url" value="${esc(s.site_url)}" readonly required></label><label>Sitemap URL<input name="sitemap_url" type="url" value="${esc(sitemapDefault)}" placeholder="https://example.com/sitemap.xml" required></label><button class="primary" type="submit">Submit sitemap to Google →</button></form><div class="notice warning">This changes the tenant’s Search Console account and always requires confirmation.</div></div>${ga4Panel(m)}${m.errors?.length?`<div class="notice warning" style="margin-top:18px">${m.errors.map(esc).join(' · ')}</div>`:''}`}
function businessProfile(){const d=state.workspace,m=d.growth_metrics||{},connected=d.integrations?.google_growth?.status==='connected',locations=m.locations||[],accounts=m.business_accounts||[],account=accounts[0];section('Business Profile',`Local presence, <span class="accent">organized.</span>`,`Review only the Business Profile assigned to this workspace.`,growthActions());if(!connected){$('viewContent').innerHTML='<div class="panel empty"><span class="empty-icon">⌖</span><h3>Connect Google Business Profile</h3><p>Use the Google account that owns or manages this tenant’s business locations.</p></div>';return}$('viewContent').innerHTML=`<div class="panel panel-pad" style="margin-bottom:18px"><form id="businessAccountForm" class="form-fields"><label>Exact Business Profile account ID<input name="account_name" value="${esc(account?.name||'')}" placeholder="accounts/123456789" pattern="accounts/[0-9]+" required></label><button class="secondary" type="submit">Verify & assign to this workspace</button></form><p class="sub">Other Business Profile accounts are never listed in this workspace.</p></div><div class="grid settings-grid"><div class="panel panel-pad"><h3>Assigned business account</h3>${account?`<div class="check"><span class="check-icon">✓</span><div><b>${esc(account.accountName||account.name)}</b><small>${esc(account.type||'Google Business Profile')} · ${esc(account.verificationState||'')}</small></div></div>`:'<div class="empty"><p>No Business Profile is assigned yet.</p></div>'}</div><div class="panel panel-pad"><h3>Locations</h3>${locations.length?locations.map(x=>`<div class="check"><span class="check-icon">⌖</span><div><b>${esc(x.title||x.name)}</b><small>${esc(x.websiteUri||'Website not added')} · ${x.phoneNumbers?'Phone added':'Phone not added'}</small></div></div>`).join(''):'<div class="empty"><p>No locations are available for the assigned account.</p></div>'}</div></div>${m.errors?.length?`<div class="notice warning" style="margin-top:18px">${m.errors.map(esc).join(' · ')}</div>`:''}`}
function heatmapVisual(h){const max=Math.max(1,...(h.points||[]).map(x=>Number(x.clicks)));return `<div class="heatmap-canvas" aria-label="Click heatmap">${(h.points||[]).map(x=>{const n=Number(x.clicks),size=18+30*n/max;return `<i title="${n} click${n===1?'':'s'}" style="left:${(Number(x.x_bucket)+.5)*5}%;top:${(Number(x.y_bucket)+.5)*5}%;width:${size}px;height:${size}px;opacity:${.35+.55*n/max}"></i>`}).join('')}<span>Top of page</span><span>Bottom of page</span></div>`}
function tracking(){const t=state.workspace.tracking||{},e=t.events||{},h=state.workspace.heatmap||{},f=h.forecast||{},meta=!!t.meta_pixel_id,tiktok=!!t.tiktok_pixel_id,heat=!!t.heatmaps_enabled,ready=meta||tiktok||heat,snippet=`<!-- In your consent callback, set window.adwiseAnalyticsConsent=true before loading this tag. -->\n<script async src="${location.origin}/tracking/${state.tenant}.js"></script>`;section('Pixels & Tracking',`Measure every <span class="accent">interaction.</span>`,`Configure tenant-specific pixels and privacy-safe click heatmaps.`);$('viewContent').innerHTML=`<div class="grid settings-grid"><div class="panel panel-pad"><h3>Tenant tracking configuration</h3><form id="trackingForm" class="form-fields"><label>Meta Pixel ID<input name="meta_pixel_id" inputmode="numeric" value="${esc(t.meta_pixel_id||'')}" placeholder="Numbers only"></label><label>TikTok Pixel ID<input name="tiktok_pixel_id" value="${esc(t.tiktok_pixel_id||'')}" placeholder="TikTok Pixel ID"></label><label>Lead event<input name="lead_event" value="${esc(e.lead||'Lead')}" required></label><label>Booking event<input name="booking_event" value="${esc(e.booking||'Schedule')}" required></label><label class="check-row"><input name="heatmaps_enabled" type="checkbox" ${heat?'checked':''}> Enable first-party click and engagement heatmaps</label><label>Approved website domains<textarea name="allowed_domains" rows="3" placeholder="example.com&#10;www.example.com">${esc((t.allowed_domains||[]).join('\n'))}</textarea><small>Exact domains only. Data from any other website is rejected.</small></label><button class="primary" type="submit">Save tracking setup →</button></form>${ready?`<div style="margin-top:20px"><h3>Website installation</h3><p class="sub">Load this only after the consent manager permits analytics. Set the consent flag to false when consent is withdrawn.</p><pre class="notice info" id="trackingSnippet" style="white-space:pre-wrap;word-break:break-all">${esc(snippet)}</pre>${btn('Copy installation tag','copy-tracking-code','secondary')}<p class="sub">Add <code>data-adwise-private</code> to any section that must never be measured. Adwise never captures text, form values, keystrokes, IP addresses or visitor IDs.</p></div>`:''}</div><div class="panel panel-pad"><h3>Installation status</h3><div class="checklist"><div class="check"><span class="check-icon">${meta?'✓':'○'}</span><div><b>Meta Pixel ${meta?'configured':'not configured'}</b></div></div><div class="check"><span class="check-icon">${tiktok?'✓':'○'}</span><div><b>TikTok Pixel ${tiktok?'configured':'not configured'}</b></div></div><div class="check"><span class="check-icon">${heat?'✓':'○'}</span><div><b>Heatmaps ${heat?'enabled':'disabled'}</b><small>${heat?'90-day retention · consent gated · workspace isolated':'Enable and add the tenant website domain.'}</small></div></div></div><div class="notice warning">Update the website privacy notice before enabling analytics heatmaps.</div></div></div><div class="panel panel-pad heatmap-panel"><div class="panel-heading"><div><h3>Website behavior heatmap</h3><p class="sub">${h.selected_page?`${esc(h.selected_page)} · previous ${h.range_days} days`:'Waiting for consented website activity.'}</p></div>${h.pages?.length?btn('Delete heatmap data','heatmap-clear','danger mini'):''}</div>${h.pages?.length?`<div class="grid kpis heatmap-kpis"><div class="card"><span class="title">Next-period views</span><div class="value">${Number(f.next_period_views||0).toLocaleString()}</div><span class="tiny">${esc(f.confidence||'low')} confidence estimate</span></div><div class="card"><span class="title">Clicks per view</span><div class="value">${esc(f.clicks_per_view||0)}</div></div><div class="card"><span class="title">Active time / view</span><div class="value">${esc(f.active_seconds_per_view||0)}s</div></div><div class="card"><span class="title">Average scroll</span><div class="value">${esc(f.average_scroll_percent||0)}%</div></div></div><div class="notice info heatmap-insights"><b>What to improve next</b>${(h.recommendations||[]).map(x=>`<p>${esc(x)}</p>`).join('')}</div>`:''}${h.selected_page?heatmapVisual(h):'<div class="empty"><p>No heatmap events received yet.</p></div>'}${h.pages?.length?`<div class="table-wrap" style="margin-top:18px"><table class="table"><thead><tr><th>Page</th><th>Views</th><th>Clicks</th><th>Active time</th><th>Max scroll</th></tr></thead><tbody>${h.pages.map(x=>`<tr><td><button class="link-button" data-action="heatmap-page" data-page="${esc(x.page_path)}">${esc(x.page_path)}</button></td><td>${Number(x.views||0).toLocaleString()}</td><td>${Number(x.clicks||0).toLocaleString()}</td><td>${Math.round(Number(x.active_seconds||0)/60)} min</td><td>${Number(x.max_scroll||0)}%</td></tr>`).join('')}</tbody></table></div>`:''}</div>`}
function accountsV2(){accounts();const panels=$('viewContent').querySelectorAll('.panel'),platforms=panels[0];if(platforms){platforms.insertAdjacentHTML('beforeend','<div class="provider"><span class="provider-logo">T</span><div class="details"><h4>TikTok Ads</h4><p>Campaign planning is available. Official TikTok Business authorization and Marketing API approval are required for publishing.</p></div><span class="badge">Not connected</span></div>');const meta=[...platforms.querySelectorAll('h4')].find(x=>x.textContent==='Meta Ads');if(meta)meta.nextElementSibling.textContent='Campaign planning is available. Official Meta Business authorization and Marketing API permissions are required for publishing.'}}
function accountsV3(){accounts();const panel=$('viewContent').querySelector('.panel'),meta=state.workspace.integrations?.meta||{status:'not_connected'},tiktok=state.workspace.integrations?.tiktok||{status:'not_connected'},metaHeading=[...panel.querySelectorAll('h4')].find(x=>x.textContent==='Meta Ads'),metaRow=metaHeading?.closest('.provider');if(metaRow){metaHeading.nextElementSibling.textContent=meta.status==='connected'?`${meta.account_name||'Meta Ads'} · ${meta.customer_id}`:'Connect Facebook and Instagram advertising through official Meta authorization.';const badge=metaRow.querySelector('.badge');badge.textContent=meta.status==='connected'?'Connected':'Not connected';badge.className=`badge ${meta.status==='connected'?'approved':''}`;metaRow.insertAdjacentHTML('afterend',`<div class="line-actions" style="margin:10px 0 20px">${btn(meta.status==='connected'?'Reconnect Meta Ads':'Connect Meta Ads','meta-connect','primary')}${meta.status==='connected'?btn('Disconnect','meta-disconnect','danger'):''}</div>`)}panel.insertAdjacentHTML('beforeend',`<div class="provider"><span class="provider-logo">T</span><div class="details"><h4>TikTok Ads</h4><p>${tiktok.status==='connected'?`${esc(tiktok.account_name||'TikTok Ads')} · Advertiser ${esc(tiktok.customer_id)}`:'Connect TikTok Ads Manager through the official advertiser authorization flow.'}</p></div><span class="badge ${tiktok.status==='connected'?'approved':''}">${tiktok.status==='connected'?'Connected':'Not connected'}</span></div><div class="line-actions" style="margin:10px 0 0">${btn(tiktok.status==='connected'?'Reconnect TikTok Ads':'Connect TikTok Ads','tiktok-connect','primary')}${tiktok.status==='connected'?btn('Disconnect','tiktok-disconnect','danger'):''}</div>`)}
function overviewV2(){overview();const integrations=state.workspace.integrations||{},connected=['google','meta','tiktok'].filter(provider=>integrations[provider]?.status==='connected'),accountCheck=[...document.querySelectorAll('.check')].find(item=>item.querySelector('b')?.textContent==='Advertising accounts'),emptyNotice=[...document.querySelectorAll('.notice.warning')].find(item=>item.textContent.includes('No live campaign metrics'));if(accountCheck){accountCheck.querySelector('.check-icon').textContent=connected.length?'✓':'○';accountCheck.querySelector('small').textContent=connected.length?`${connected.map(provider=>provider==='google'?'Google Ads':provider==='meta'?'Meta Ads':'TikTok Ads').join(', ')} connected to this workspace.`:'No advertising platform is connected to this workspace.'}if(emptyNotice&&connected.length){emptyNotice.className='notice info';emptyNotice.textContent='Live advertising data is available from the connected platforms. Campaign changes still require explicit confirmation.'}}
function render(){if(!state.workspace)return;({overview:overviewV2,analytics:analyticsV2,seo,business:businessProfile,tracking,campaigns,approvals,assistant,accounts:accountsV4,settings,activity}[state.view]||overviewV2)();document.querySelectorAll('select[name="provider"]').forEach(select=>{if(!select.querySelector('option[value="tiktok"]'))select.insertAdjacentHTML('beforeend','<option value="tiktok">TikTok Ads</option>')})}
async function syncAnalyticsRange(range){if(state.busy)return;try{state.busy=true;state.analyticsRange=range;state.workspace.google_metrics=await req(`/api/workspaces/${encodeURIComponent(state.tenant)}/integrations/google/sync?range=${encodeURIComponent(range)}&force=true`,'POST',{});render();toast(`${state.workspace.google_metrics.period} analytics loaded.`)}catch(e){toast(e.message,true)}finally{state.busy=false}}
async function heatmapAction(act,page=''){if(state.busy)return;try{state.busy=true;const base=`/api/workspaces/${encodeURIComponent(state.tenant)}/heatmap`;if(act==='heatmap-clear'){if(!confirm('Delete all heatmap events for this workspace? This cannot be undone.'))return;await req(base,'DELETE',{});await loadTenant(state.tenant);toast('Heatmap data deleted.');return}state.workspace.heatmap=await req(`${base}?page=${encodeURIComponent(page)}`);render()}catch(e){toast(e.message,true)}finally{state.busy=false}}
async function seedAnalysis(){if(state.busy)return;if(!confirm('Send this workspace’s aggregate campaign and website metrics to Seed for advisory analysis? No live changes will be made.'))return;try{state.busy=true;toast('Seed is analyzing current performance…');const result=await req(`/api/workspaces/${encodeURIComponent(state.tenant)}/agent/performance-analysis`,'POST',{});state.workspace.seed_analysis={analysis:result.analysis,model:result.model,created_at:result.created_at};render();toast(result.cached?'Current Seed analysis loaded.':'New Seed analysis completed.')}catch(e){toast(e.message,true)}finally{state.busy=false}}
function updateAssetRequirements(){const provider=$('campaignForm').elements.provider.value,text={google:'Google Search uses headlines and descriptions during the publishing step. Optional images must be public HTTPS URLs.',meta:'Meta requires at least one public HTTPS image or video URL. Recommended starting formats: square/vertical images and short vertical video.',tiktok:'TikTok requires at least one public HTTPS video URL. Use a mobile-first vertical video with clear audio, captions and a strong opening.'}[provider];$('assetRequirements').textContent=text}
async function suggestAudience(){if(state.busy)return;const f=$('campaignForm'),service=f.elements.service.value.trim(),location=f.elements.audience_location.value.trim(),box=$('campaignResearch');if(!service||!location){toast('Add the service and target location before researching.',true);return}const payload={provider:f.elements.provider.value,objective:f.elements.objective.value,service,budget_aed:f.elements.budget_aed.value||'0',audience_location:location,landing_url:f.elements.landing_url.value.trim(),brief:f.elements.brief.value.trim()};try{state.busy=true;box.className='notice info';box.textContent='Researching current platform and business sources…';const x=await req(`/api/workspaces/${encodeURIComponent(state.tenant)}/agent/recommend-campaign`,'POST',payload),r=x.recommendation,e=x.evidence;f.elements.audience_source.value='suggested';f.elements.audience_age_min.value=r.audience_age_min;f.elements.audience_age_max.value=r.audience_age_max;f.elements.audience_gender.value=r.audience_gender;f.elements.audience_interests.value=r.audience_interests.join(', ');f.elements.placements.value=r.placements.join(', ');f.elements.call_to_action.value=r.call_to_action;f.elements.research_payload.value=JSON.stringify({recommendation:r,evidence:e});const list=(title,items)=>items?.length?`<p><b>${esc(title)}:</b> ${items.map(esc).join(' · ')}</p>`:'';box.innerHTML=`<p><b>Research confidence: ${esc(r.confidence)}</b> · ${esc(r.audience_summary)}</p><p class="sub">AI: ${esc(e.ai_provider||'configured provider')} · Research: ${esc(e.research_mode||'source grounded')}</p>${list('Creative angles',r.creative_angles)}${list('Assets to provide',r.asset_requirements)}${list('Missing inputs',r.missing_inputs)}${list('Assumptions',r.assumptions)}${e.sources?.length?`<p><b>Sources:</b> ${e.sources.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)}</a>`).join(' · ')}</p>`:''}<p class="sub">Advisory draft only. Review account eligibility and current specifications before publishing.</p>`;toast('Research-backed recommendation added. Review every field.');updateAssetRequirements()}catch(e){box.className='notice warning';box.textContent=e.message;toast(e.message,true)}finally{state.busy=false}}
async function action(act,id){if(state.busy)return;const tid=encodeURIComponent(state.tenant), base=`/api/workspaces/${tid}`;try{state.busy=true;if(act==='logout'){await req('/api/logout','POST',{});showAuth();return}if(act==='new-campaign'){$('campaignForm').reset();$('campaignResearch').className='notice info hidden';$('campaignResearch').textContent='';$('campaignDialog').showModal();return}if(act==='close-dialog'){$('campaignDialog').close();return}if(act==='close-publish'){$('publishDialog').close();return}if(act==='publish-google'){const c=state.workspace.campaigns.find(x=>x.id===id);if(!c)throw Error('Campaign not found');const f=$('publishForm');f.reset();f.elements.campaign_id.value=c.id;f.elements.daily_budget_aed.value=Math.min(Number(c.budget_aed),70).toFixed(2);f.elements.final_url.value=c.landing_url;f.elements.keywords.value=[c.service,`${c.service} Abu Dhabi`,`${c.service} near me`].filter(Boolean).join('\n');f.elements.headlines.value=[c.name.slice(0,30),(c.service||'Be Relax Massage').slice(0,30),'Book Your Massage Today'].join('\n');f.elements.descriptions.value=[(c.copy||'Relax with professional spa treatments and book your appointment today.').slice(0,90),'Professional massage treatments in Abu Dhabi. Book your relaxing visit online.'].join('\n');f.elements.callouts.value='Professional Therapists\nEasy Online Booking\nRelaxing Spa Experience';$('publishDialog').showModal();return}if(act==='go-assistant'||act==='go-campaigns'){state.view=act==='go-assistant'?'assistant':'campaigns';render();return}if(act==='google-connect'){const x=await req(`${base}/integrations/google/start`,'POST',{});window.location.assign(x.authorization_url);return}if(act==='google-sync'){state.workspace.google_metrics=await req(`${base}/integrations/google/sync?range=${encodeURIComponent(state.analyticsRange)}&force=true`,'POST',{});render();toast('Live Google Ads metrics synced.');return}if(act==='google-disconnect'){if(!confirm('Disconnect Google Ads from this workspace?'))return;await req(`${base}/integrations/google/disconnect`,'POST',{});await loadTenant(state.tenant);toast('Google Ads disconnected.');return}if(act==='save-plan'){if(!state.lastAI)return;state.view='campaigns';render();$('campaignForm').reset();for(let k of ['provider','objective','service','budget_aed']){$('campaignForm').elements[k].value=state.lastAI.input[k]}$('campaignForm').elements['name'].value=state.lastAI.input.service+' — campaign';$('campaignForm').elements['brief'].value=state.lastAI.plan.slice(0,6000);$('campaignDialog').showModal();toast('Plan attached. Review ad copy and add an HTTPS booking URL.');return}if(act==='approve'&&!confirm('Approve this campaign plan internally? NO ads will be published.'))return;if(act==='stop'&&!confirm('Stop internal planning and approvals for this spa?'))return;if(act==='archive'&&!confirm('Archive this internal campaign proposal?'))return;let endpoint={submit:'submit',approve:'approve',reject:'reject',archive:'archive'}[act];if(endpoint){await req(`${base}/campaigns/${encodeURIComponent(id)}/${endpoint}`,'POST',{});toast(`Campaign ${endpoint} completed (internal only).`)}else if(act==='stop'||act==='resume'){await req(`${base}/${act==='stop'?'emergency-stop':'resume-automation'}`,'POST',{});toast(act==='stop'?'Emergency stop enabled.':'Supervised planning resumed.')}await loadTenant(state.tenant)}catch(e){toast(e.message,true)}finally{state.busy=false}}
function metaPublishAction(act,id){if(act==='close-meta-publish'){$('metaPublishDialog').close();return}const c=state.workspace.campaigns.find(x=>x.id===id);if(!c){toast('Campaign not found',true);return}const f=$('metaPublishForm'),spec=c.spec||{};f.reset();f.elements.campaign_id.value=c.id;f.elements.daily_budget_aed.value=Math.min(Number(c.budget_aed)/7,70).toFixed(2);f.elements.final_url.value=c.landing_url||'';f.elements.primary_text.value=(c.copy||`Discover ${c.service||'our wellness services'} and book your visit.`).slice(0,2200);f.elements.headline.value=c.name.slice(0,255);f.elements.image_url.value=(spec.image_urls||[])[0]||'';f.elements.call_to_action.value=['BOOK_NOW','LEARN_MORE','CONTACT_US'].includes(spec.call_to_action)?spec.call_to_action:'BOOK_NOW';metaPublishAssetsSummary();$('metaPublishDialog').showModal()}
async function googleAccountAction(act){if(act==='close-google-account'){$('googleAccountDialog').close();return}if(state.busy)return;try{state.busy=true;const x=await req(`/api/workspaces/${encodeURIComponent(state.tenant)}/integrations/google/accounts`);state.googleAccounts=x.accounts||[];const select=$('googleAccountForm').elements.account;select.innerHTML=state.googleAccounts.map((a,i)=>`<option value="${i}">${esc(a.account_name)} · Customer ${esc(a.customer_id)}${a.login_customer_id?` · Manager ${esc(a.login_customer_id)}`:''}</option>`).join('');if(!state.googleAccounts.length)throw Error('No accessible Google Ads customer accounts were found.');$('googleAccountDialog').showModal()}catch(e){toast(e.message,true)}finally{state.busy=false}}
async function googleAction(act,id){if(state.busy)return;const base=`/api/workspaces/${encodeURIComponent(state.tenant)}/integrations/google`;try{state.busy=true;if(act==='google-conversions-setup'){if(!confirm('Create or verify all three Google Ads conversion goals? Website tags will still need installation.'))return;const x=await req(`${base}/conversions/setup`,'POST',{});await loadTenant(state.tenant);toast(`${x.created} conversion goal${x.created===1?'':'s'} created; all three are configured.`);return}const status=act==='google-campaign-pause'?'PAUSED':'ENABLED';if(!confirm(`${status==='PAUSED'?'Pause':'Enable'} Google Ads campaign ${id}? This changes the live account immediately.`))return;await req(`${base}/campaigns/${encodeURIComponent(id)}/status`,'POST',{status});state.workspace.google_metrics=await req(`${base}/sync?range=${encodeURIComponent(state.analyticsRange)}&force=true`,'POST',{});render();toast(`Live campaign ${status==='PAUSED'?'paused':'enabled'}.`)}catch(e){toast(e.message,true)}finally{state.busy=false}}
