async function init(){const q=new URLSearchParams(location.search),requestedView=q.get('view'),views=['overview','analytics','seo','business','tracking','campaigns','approvals','assistant','accounts','settings','activity'];if(q.get('tenant'))state.tenant=q.get('tenant');if(views.includes(requestedView))state.view=requestedView;if(q.has('google')||q.has('meta')||q.has('tiktok'))state.view='accounts';if(q.has('google_growth'))state.view='seo';try{await refresh();autoSyncConnectedData();for(const provider of ['google','google_growth','meta','tiktok'])if(q.has(provider)){const result=q.get(provider),name={google:'Google Ads',google_growth:'Google Growth',meta:'Meta Ads',tiktok:'TikTok Ads'}[provider];if(provider==='meta'){const reason=q.get('reason')||'';toast(metaReasons[reason]||(result==='connected'?'Meta Ads connected.':result==='authorized'?'Meta authorized. Choose the ad account, Page, Instagram account and Pixel for this workspace.':'Meta authorization failed.'),result==='error'||reason==='permissions');history.replaceState({},'',location.pathname);break}toast(result==='connected'?`${name} connected successfully.`:result==='authorized'?(provider==='google'?'Google Ads authorized. Choose the account for this workspace.':`${name} authorized; API access approval is still pending.`):`${name} authorization failed.`,result==='error');history.replaceState({},'',location.pathname);break}}catch(e){showAuth()}}
document.addEventListener('click',ev=>{const feedback=ev.target.closest('button,a,[role="button"]');if(feedback){feedback.classList.remove('tap-feedback');void feedback.offsetWidth;feedback.classList.add('tap-feedback');setTimeout(()=>feedback.classList.remove('tap-feedback'),240)}const themeButton=ev.target.closest('[data-theme-toggle]');if(themeButton){applyProductTheme(document.documentElement.dataset.productTheme==='dark'?'light':'dark');return}const button=ev.target.closest('[data-action],[data-view]');if(!button)return;if(button.dataset.view){state.view=button.dataset.view;setMobileMenu(false);render();return}const act=button.dataset.action;if(act==='toggle-mobile-menu'){setMobileMenu(!document.body.classList.contains('mobile-menu-open'));return}if(act==='close-mobile-menu'){setMobileMenu(false);return}if(act==='copy-tracking-code'){navigator.clipboard.writeText($('trackingSnippet')?.textContent||'').then(()=>toast('Installation tag copied.')).catch(()=>toast('Copy the installation tag manually.',true));return}if(act==='suggest-audience')suggestAudience();else if(act==='analytics-range')syncAnalyticsRange(button.dataset.range);else if(act==='seed-analyze')seedAnalysis();else if(act==='heatmap-page'||act==='heatmap-clear')heatmapAction(act,button.dataset.page||'');else if(act.startsWith('growth-'))growthAction(act);else if(act==='google-select-account'||act==='close-google-account')googleAccountAction(act);else if(act==='publish-meta'||act==='close-meta-publish')metaPublishAction(act,button.dataset.id);else if(/^meta-(assets|health|sync|approve|reject|pause|enable|budget)$/.test(act)||act==='close-meta-assets')metaAction(act,button.dataset.id);else if(/^((meta|tiktok)-(connect|disconnect))$/.test(act))providerAction(act);else if(act==='google-conversions-setup'||act==='google-campaign-pause'||act==='google-campaign-enable')googleAction(act,button.dataset.id);else action(act,button.dataset.id)});
