function googleTextAssets(value,type){const marker=type==='HEADLINE'?'H':'D',pattern=new RegExp(`^\\[(${marker}[123])\\]\\s*`,'i');return String(value||'').split('\n').map(x=>x.trim()).filter(Boolean).map(line=>{const match=line.match(pattern),asset={text:line.replace(pattern,'').trim()};if(match)asset.pinned_field=`${type}_${match[1].slice(1)}`;return asset})}
function googleSchedules(value){const minutes={0:'ZERO',15:'FIFTEEN',30:'THIRTY',45:'FORTY_FIVE'};return String(value||'').split('\n').map(x=>x.trim()).filter(Boolean).map(line=>{const match=line.match(/^(MONDAY|TUESDAY|WEDNESDAY|THURSDAY|FRIDAY|SATURDAY|SUNDAY)\s+(\d{1,2}):(00|15|30|45)-(\d{1,2}):(00|15|30|45)$/i);if(!match)throw Error(`Invalid ad schedule: ${line}`);return{day_of_week:match[1].toUpperCase(),start_hour:Number(match[2]),start_minute:minutes[Number(match[3])],end_hour:Number(match[4]),end_minute:minutes[Number(match[5])]}})}
